from datetime import datetime

import pytest
from isoduration import add_duration


class TestValidParsing:
    """Test valid duration strings are parsed correctly."""

    def test_single_day(self):
        assert add_duration(datetime(2025, 3, 10), "P1D") == datetime(2025, 3, 11)

    def test_multiple_days(self):
        assert add_duration(datetime(2025, 3, 10), "P10D") == datetime(2025, 3, 20)

    def test_leading_zeros_days(self):
        assert add_duration(datetime(2025, 3, 10), "P03D") == datetime(2025, 3, 13)

    def test_single_month(self):
        assert add_duration(datetime(2025, 3, 10), "P1M") == datetime(2025, 4, 10)

    def test_multiple_months(self):
        assert add_duration(datetime(2025, 3, 10), "P5M") == datetime(2025, 8, 10)

    def test_single_year(self):
        assert add_duration(datetime(2025, 3, 10), "P1Y") == datetime(2026, 3, 10)

    def test_multiple_years(self):
        assert add_duration(datetime(2025, 3, 10), "P3Y") == datetime(2028, 3, 10)

    def test_weeks(self):
        assert add_duration(datetime(2025, 3, 10), "P2W") == datetime(2025, 3, 24)

    def test_single_hour(self):
        assert add_duration(datetime(2025, 3, 10, 8), "PT1H") == datetime(2025, 3, 10, 9)

    def test_multiple_hours(self):
        assert add_duration(datetime(2025, 3, 10, 8), "PT5H") == datetime(2025, 3, 10, 13)

    def test_single_minute(self):
        assert add_duration(datetime(2025, 3, 10, 8), "PT1M") == datetime(2025, 3, 10, 8, 1)

    def test_multiple_minutes(self):
        assert add_duration(datetime(2025, 3, 10, 8), "PT30M") == datetime(2025, 3, 10, 8, 30)

    def test_single_second(self):
        assert add_duration(datetime(2025, 3, 10, 8), "PT1S") == datetime(2025, 3, 10, 8, 0, 1)

    def test_multiple_seconds(self):
        assert add_duration(datetime(2025, 3, 10, 8), "PT45S") == datetime(2025, 3, 10, 8, 0, 45)

    def test_hours_and_minutes(self):
        assert add_duration(datetime(2025, 3, 10, 8), "PT1H30M") == datetime(2025, 3, 10, 9, 30)

    def test_hours_minutes_seconds(self):
        assert add_duration(
            datetime(2025, 3, 10, 8, 0, 0),
            "PT1H30M45S",
        ) == datetime(2025, 3, 10, 9, 30, 45)

    def test_years_and_months(self):
        assert add_duration(datetime(2025, 3, 10), "P1Y2M") == datetime(2026, 5, 10)

    def test_years_months_days(self):
        assert add_duration(datetime(2025, 3, 10), "P1Y2M10D") == datetime(2026, 5, 20)

    def test_years_months_days_hours(self):
        assert add_duration(
            datetime(2025, 3, 10, 8),
            "P1Y2M10DT2H",
        ) == datetime(2026, 5, 20, 10)

    def test_full_duration(self):
        assert add_duration(
            datetime(2025, 3, 10, 8, 15, 30),
            "P1Y2M10DT2H30M45S",
        ) == datetime(2026, 5, 20, 10, 46, 15)

    def test_explicit_plus_sign(self):
        assert add_duration(datetime(2025, 3, 10), "+P1D") == datetime(2025, 3, 11)

    def test_leading_zeros_on_all_components(self):
        assert add_duration(
            datetime(2025, 3, 10, 8, 15, 30),
            "P01Y02M03DT04H05M06S",
        ) == datetime(2026, 5, 13, 12, 20, 36)


class TestFractionalDurations:
    """Test fractional components (only on the last component)."""

    def test_fractional_seconds_dot(self):
        result = add_duration(
            datetime(2025, 3, 10, 8, 0, 0),
            "PT1.5S",
        )
        assert result == datetime(2025, 3, 10, 8, 0, 1, 500000)

    def test_fractional_seconds_comma(self):
        result = add_duration(
            datetime(2025, 3, 10, 8, 0, 0),
            "PT1,5S",
        )
        assert result == datetime(2025, 3, 10, 8, 0, 1, 500000)

    def test_fractional_minutes(self):
        result = add_duration(
            datetime(2025, 3, 10, 8, 0, 0),
            "PT1.5M",
        )
        assert result == datetime(2025, 3, 10, 8, 1, 30)

    def test_fractional_hours(self):
        result = add_duration(
            datetime(2025, 3, 10, 8, 0, 0),
            "PT2.5H",
        )
        assert result == datetime(2025, 3, 10, 10, 30, 0)

    def test_fractional_days(self):
        result = add_duration(
            datetime(2025, 3, 10, 0, 0, 0),
            "P0.5D",
        )
        assert result == datetime(2025, 3, 10, 12, 0, 0)

    def test_fractional_weeks(self):
        result = add_duration(
            datetime(2025, 3, 10, 0, 0, 0),
            "P0.5W",
        )
        # 0.5 weeks = 3.5 days = 3 days + 12 hours
        assert result == datetime(2025, 3, 13, 12, 0, 0)

    def test_fractional_seconds_many_decimals(self):
        # Test rounding to microseconds
        result = add_duration(
            datetime(2025, 3, 10, 8, 0, 0),
            "PT0.0000005S",
        )
        # 0.0000005 seconds = 0.5 microseconds, round to 1 microsecond
        assert result == datetime(2025, 3, 10, 8, 0, 0, 1)


class TestMonthYearApplication:
    """Test special rules for month/year application with day clamping."""

    def test_month_overflow_january_to_february_leap_year(self):
        # 2024-01-31 + P1M = 2024-02-29 (last day of Feb in leap year)
        assert add_duration(datetime(2024, 1, 31), "P1M") == datetime(2024, 2, 29)

    def test_month_overflow_january_to_february_non_leap_year(self):
        # 2025-01-31 + P1M = 2025-02-28 (last day of Feb in non-leap year)
        assert add_duration(datetime(2025, 1, 31), "P1M") == datetime(2025, 2, 28)

    def test_month_overflow_march_to_april(self):
        # 2024-03-31 + P1M = 2024-04-30 (last day of April)
        assert add_duration(datetime(2024, 3, 31), "P1M") == datetime(2024, 4, 30)

    def test_multiple_months_overflow(self):
        # 2024-01-31 + P2M = 2024-03-31 (March has 31 days)
        assert add_duration(datetime(2024, 1, 31), "P2M") == datetime(2024, 3, 31)

    def test_year_and_month_overflow(self):
        # 2024-02-29 + P1Y1M = 2025-03-29 (spec example)
        assert add_duration(datetime(2024, 2, 29), "P1Y1M") == datetime(2025, 3, 29)

    def test_many_months_overflow_to_year(self):
        # 2024-01-31 + P13M = 2025-02-28 (13 months = 1 year 1 month)
        assert add_duration(datetime(2024, 1, 31), "P13M") == datetime(2025, 2, 28)

    def test_month_preserves_time(self):
        # Time components should be preserved
        assert add_duration(
            datetime(2024, 1, 31, 15, 30, 45),
            "P1M",
        ) == datetime(2024, 2, 29, 15, 30, 45)

    def test_months_then_days(self):
        # 2024-01-31 + P1M1D = 2024-02-29 + 1 day = 2024-03-01
        assert add_duration(datetime(2024, 1, 31), "P1M1D") == datetime(2024, 3, 1)


class TestNegativeDurations:
    """Test negative durations (prefix with -)."""

    def test_negative_days(self):
        assert add_duration(datetime(2025, 3, 10), "-P1D") == datetime(2025, 3, 9)

    def test_negative_months(self):
        assert add_duration(datetime(2025, 3, 10), "-P1M") == datetime(2025, 2, 10)

    def test_negative_months_with_day_clamping(self):
        # 2024-03-31 - P1M = 2024-02-29
        assert add_duration(datetime(2024, 3, 31), "-P1M") == datetime(2024, 2, 29)

    def test_negative_years(self):
        assert add_duration(datetime(2025, 3, 10), "-P1Y") == datetime(2024, 3, 10)

    def test_negative_hours(self):
        assert add_duration(datetime(2025, 3, 10, 10), "-PT1H") == datetime(2025, 3, 10, 9)

    def test_negative_multiple_components(self):
        # 2024-03-01 - P1M1D = 2024-02-01 - 1 day = 2024-01-31
        assert add_duration(datetime(2024, 3, 1), "-P1M1D") == datetime(2024, 1, 31)

    def test_negative_fractional_seconds(self):
        result = add_duration(
            datetime(2025, 3, 10, 8, 0, 2),
            "-PT1.5S",
        )
        assert result == datetime(2025, 3, 10, 8, 0, 0, 500000)

    def test_negative_full_duration(self):
        result = add_duration(
            datetime(2026, 5, 20, 10, 46, 15),
            "-P1Y2M10DT2H30M45S",
        )
        assert result == datetime(2025, 3, 10, 8, 15, 30)


class TestWeeksCannot beCombined:
    """Test that weeks cannot be combined with other components."""

    def test_weeks_alone_valid(self):
        assert add_duration(datetime(2025, 3, 10), "P2W") == datetime(2025, 3, 24)

    def test_weeks_with_days_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P2W3D")

    def test_weeks_with_time_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P2WT1H")

    def test_weeks_with_months_invalid(self):
        with pytest.raises(ValueError):
            add_duration(datetime(2025, 3, 10), "P1M2W")


