class TestEdgeCases:
    """Test edge cases and boundary conditions."""

    def test_zero_days(self):
        # P0D should be valid but do nothing
        assert add_duration(datetime(2025, 3, 10), "P0D") == datetime(2025, 3, 10)

    def test_zero_seconds(self):
        assert add_duration(
            datetime(2025, 3, 10, 8, 0, 0),
            "PT0S",
        ) == datetime(2025, 3, 10, 8, 0, 0)

    def test_midnight_crossing(self):
        result = add_duration(datetime(2025, 3, 10, 23, 30), "PT1H")
        assert result == datetime(2025, 3, 11, 0, 30)

    def test_month_boundary_crossing(self):
        result = add_duration(datetime(2025, 3, 31, 23, 30), "P1D1H")
        assert result == datetime(2025, 4, 1, 0, 30)

    def test_year_boundary_crossing(self):
        result = add_duration(datetime(2025, 12, 31), "P1D")
        assert result == datetime(2026, 1, 1)

    def test_leap_year_february_29(self):
        # Adding 1 year to leap day
        result = add_duration(datetime(2024, 2, 29), "P1Y")
        assert result == datetime(2025, 2, 28)

    def test_multiple_year_leap_cycle(self):
        # 2024 is leap year, 2028 is leap year
        result = add_duration(datetime(2024, 2, 29), "P4Y")
        assert result == datetime(2028, 2, 29)

    def test_subtract_across_leap_year_boundary(self):
        # From 2024-03-01 subtract P1D crosses leap day
        result = add_duration(datetime(2024, 3, 1), "-P1D")
        assert result == datetime(2024, 2, 29)

    def test_datetime_with_microseconds(self):
        result = add_duration(
            datetime(2025, 3, 10, 8, 0, 0, 500000),
            "PT0.5S",
        )
        assert result == datetime(2025, 3, 10, 8, 0, 1)

    def test_very_large_duration(self):
        # 100 years
        result = add_duration(datetime(1925, 1, 1), "P100Y")
        assert result == datetime(2025, 1, 1)

    def test_datetime_min_year_boundary(self):
        # datetime.min is year 1
        # Adding negative duration from early date should raise ValueError
        with pytest.raises(ValueError):
            add_duration(datetime(1, 1, 1), "-P1D")

    def test_datetime_max_year_boundary(self):
        # datetime.max is year 9999
        # Adding positive duration to late date should raise ValueError
        with pytest.raises(ValueError):
            add_duration(datetime(9999, 12, 31), "P1D")

    def test_large_negative_duration_overflow(self):
        with pytest.raises(ValueError):
            add_duration(datetime(1, 6, 15), "-P1000Y")

    def test_fractional_rounding_to_microsecond(self):
        # Test that fine fractions round to nearest microsecond
        result = add_duration(
            datetime(2025, 3, 10, 8, 0, 0),
            "PT0.0000001S",
        )
        # 0.0000001 seconds = 0.1 microseconds, rounds to 0
        assert result == datetime(2025, 3, 10, 8, 0, 0, 0)

    def test_fractional_rounding_half_microsecond_up(self):
        # 0.5 microseconds should round to 1 microsecond
        result = add_duration(
            datetime(2025, 3, 10, 8, 0, 0),
            "PT0.0000005S",
        )
        assert result == datetime(2025, 3, 10, 8, 0, 0, 1)

